<?php
/**
 * Retrieve the 'wpbp/add-one' ability and execute it with the supplied number.
 *
 * @param int $number The number to pass to the ability.
 * @return mixed The result of the ability execution, or a WP_Error on failure.
 */
function wpbp_abilities_api_003( int $number ) {
	if ( ! function_exists( 'wp_get_ability' ) ) {
		return new WP_Error(
			'wpbp_abilities_api_unavailable',
			'The Abilities API is not available.'
		);
	}

	$ability = wp_get_ability( 'wpbp/add-one' );

	if ( ! $ability ) {
		return new WP_Error(
			'wpbp_ability_not_found',
			'The ability "wpbp/add-one" is not registered.'
		);
	}

	return $ability->execute( array( 'number' => $number ) );
}
