<?php
/**
 * Plugin Name: WPBP REST Visible Ability
 * Description: Registers an Abilities API ability exposed through the Abilities REST API.
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Register the ability category.
 */
add_action( 'wp_abilities_api_categories_init', 'wpbp_register_rest_abilities_category' );

function wpbp_register_rest_abilities_category() {
	if ( ! function_exists( 'wp_register_ability_category' ) ) {
		return;
	}

	wp_register_ability_category(
		'wpbp-rest-abilities',
		array(
			'label'       => __( 'WPBP REST Abilities', 'wpbp' ),
			'description' => __( 'Abilities that are available through the Abilities REST API.', 'wpbp' ),
		)
	);
}

/**
 * Register the ability.
 */
add_action( 'wp_abilities_api_init', 'wpbp_register_rest_visible_ability' );

function wpbp_register_rest_visible_ability() {
	if ( ! function_exists( 'wp_register_ability' ) ) {
		return;
	}

	wp_register_ability(
		'wpbp/rest-visible',
		array(
			'label'               => __( 'REST Visible Ability', 'wpbp' ),
			'description'         => __( 'Returns a simple message and is available through the Abilities REST API.', 'wpbp' ),
			'category'            => 'wpbp-rest-abilities',
			'input_schema'        => array(
				'type'                 => 'object',
				'properties'           => array(
					'name' => array(
						'type'        => 'string',
						'description' => __( 'Optional name to include in the message.', 'wpbp' ),
					),
				),
				'additionalProperties' => false,
			),
			'output_schema'       => array(
				'type'       => 'object',
				'properties' => array(
					'message' => array(
						'type'        => 'string',
						'description' => __( 'The resulting message.', 'wpbp' ),
					),
				),
				'required'   => array( 'message' ),
			),
			'execute_callback'    => 'wpbp_execute_rest_visible_ability',
			'permission_callback' => 'wpbp_rest_visible_ability_permission',
			'meta'                => array(
				'show_in_rest' => true,
				'annotations'  => array(
					'readonly'    => true,
					'destructive' => false,
					'idempotent'  => true,
				),
			),
		)
	);
}

/**
 * Permission callback.
 *
 * @return bool
 */
function wpbp_rest_visible_ability_permission() {
	return current_user_can( 'read' );
}

/**
 * Execute callback.
 *
 * @param array|null $input Input data.
 * @return array
 */
function wpbp_execute_rest_visible_ability( $input = array() ) {
	$name = isset( $input['name'] ) ? sanitize_text_field( $input['name'] ) : '';

	return array(
		'message' => '' !== $name
			? sprintf( __( 'Hello, %s!', 'wpbp' ), $name )
			: __( 'Hello from a REST visible ability!', 'wpbp' ),
	);
}
