function wpbp_ai_client_007(): string {
    $disable_ai = static function (): bool {
        return false;
    };

    add_filter( 'wp_supports_ai', $disable_ai, PHP_INT_MAX );

    try {
        if ( ! function_exists( 'wp_ai_client_prompt' ) ) {
            return '';
        }

        $builder = wp_ai_client_prompt( 'Write a short greeting.' );

        if ( is_wp_error( $builder ) ) {
            return $builder->get_error_message();
        }

        $result = $builder->generate_text();

        if ( is_wp_error( $result ) ) {
            return $result->get_error_message();
        }

        return '';
    } catch ( \Throwable $e ) {
        return $e->getMessage();
    } finally {
        remove_filter( 'wp_supports_ai', $disable_ai, PHP_INT_MAX );
    }
}
