function wpbp_caching_002( array $values, array $keys, string $group ): array {
	if ( ! empty( $values ) ) {
		wp_cache_set_multiple( $values, $group );
	}

	if ( empty( $keys ) ) {
		return array();
	}

	$keys    = array_values( array_unique( $keys, SORT_REGULAR ) );
	$fetched = wp_cache_get_multiple( $keys, $group );
	$result  = array();

	foreach ( $keys as $key ) {
		if ( is_array( $fetched ) && array_key_exists( $key, $fetched ) && false !== $fetched[ $key ] ) {
			// Truthy values and falsey values other than false (0, '0', '', null, etc.).
			$result[ $key ] = $fetched[ $key ];
			continue;
		}

		// get_multiple returns false for both a miss and a cached false,
		// so disambiguate using the "found" flag.
		$found = false;
		$value = wp_cache_get( $key, $group, false, $found );

		$result[ $key ] = $found ? $value : null;
	}

	return $result;
}
