function wpbp_caching_006( array $values, array $keys, string $group, array $salt ): array {
	// Store the batch under the supplied salt.
	if ( ! empty( $values ) ) {
		wp_cache_set_multiple_salted( $values, $group, $salt );
	}

	// Build a salt that is guaranteed to differ from the current one.
	$stale_salt = array( 'wpbp_stale_salt', $salt );

	$current = array();
	$stale   = array();

	if ( ! empty( $keys ) ) {
		$current = wp_cache_get_multiple_salted( $keys, $group, $salt );
		$stale   = wp_cache_get_multiple_salted( $keys, $group, $stale_salt );
	}

	// Normalize so every requested key is present, defaulting to false.
	$current_result = array();
	$stale_result   = array();

	foreach ( $keys as $key ) {
		$current_result[ $key ] = array_key_exists( $key, $current ) ? $current[ $key ] : false;
		$stale_result[ $key ]   = array_key_exists( $key, $stale ) ? $stale[ $key ] : false;
	}

	return array(
		'current' => $current_result,
		'stale'   => $stale_result,
	);
}
