<?php
/**
 * Get user IDs whose user meta for a given key exactly matches a given value.
 *
 * @param string $meta_key   The user meta key to search.
 * @param string $meta_value The value that the meta must exactly match.
 * @return array List of matching user IDs (integers).
 */
function wpbp_comments_users_002( string $meta_key, string $meta_value ): array {
	$meta_key = trim( $meta_key );

	if ( '' === $meta_key ) {
		return array();
	}

	$query = new WP_User_Query(
		array(
			'fields'      => 'ID',
			'orderby'     => 'ID',
			'order'       => 'ASC',
			'count_total' => false,
			'meta_query'  => array(
				array(
					'key'     => $meta_key,
					'value'   => $meta_value,
					'compare' => '=',
					'type'    => 'CHAR',
				),
			),
		)
	);

	$results = $query->get_results();

	if ( empty( $results ) || ! is_array( $results ) ) {
		return array();
	}

	return array_map( 'intval', $results );
}
