/**
 * Safely retrieve connector data for the given connector ID using the public Connectors API.
 *
 * @param string $connector_id The connector ID.
 * @return array|null Connector data if registered, null otherwise.
 */
function wpbp_connectors_api_002( string $connector_id ): ?array {
	if ( '' === $connector_id ) {
		return null;
	}

	if ( ! wp_is_connector_registered( $connector_id ) ) {
		return null;
	}

	$connector = wp_get_connector( $connector_id );

	return is_array( $connector ) ? $connector : null;
}
