function wpbp_connectors_api_006( string $type ): array {
	$ids = array();

	foreach ( wp_get_connectors() as $key => $connector ) {
		if ( is_array( $connector ) ) {
			$connector_type = $connector['type'] ?? null;
			$connector_id   = $connector['id'] ?? $key;
		} elseif ( is_object( $connector ) ) {
			$connector_type = is_callable( array( $connector, 'get_type' ) )
				? $connector->get_type()
				: ( $connector->type ?? null );

			$connector_id = is_callable( array( $connector, 'get_id' ) )
				? $connector->get_id()
				: ( $connector->id ?? $key );
		} else {
			continue;
		}

		if ( $connector_type === $type ) {
			$ids[] = (string) $connector_id;
		}
	}

	sort( $ids, SORT_STRING );

	return $ids;
}
