function wpbp_connectors_api_009( string $connector_id ): ?bool {
	if ( ! function_exists( 'wp_is_connector_registered' ) || ! wp_is_connector_registered( $connector_id ) ) {
		return null;
	}

	if ( ! function_exists( 'wp_get_connector' ) ) {
		return null;
	}

	$connector = wp_get_connector( $connector_id );

	if ( ! is_array( $connector ) ) {
		return null;
	}

	if ( isset( $connector['plugin'] ) && is_array( $connector['plugin'] ) && isset( $connector['plugin']['is_active'] ) && is_callable( $connector['plugin']['is_active'] ) ) {
		return (bool) call_user_func( $connector['plugin']['is_active'] );
	}

	return null;
}
