function wpbp_connectors_api_011( string $connector_id ): bool {
	// Validate against the Connectors API ID pattern (lowercase alphanumerics, hyphens, underscores).
	// \z ensures no trailing newline slips through.
	if ( 1 !== preg_match( '/^[a-z0-9_-]+\z/', $connector_id ) ) {
		return false;
	}

	if ( ! class_exists( 'WP_Connector_Registry' ) ) {
		return false;
	}

	$registry = null;

	if ( method_exists( 'WP_Connector_Registry', 'get_instance' ) ) {
		$registry = WP_Connector_Registry::get_instance();
	}

	if ( ! is_object( $registry ) || ! method_exists( $registry, 'register' ) ) {
		return false;
	}

	if ( method_exists( $registry, 'is_registered' ) && $registry->is_registered( $connector_id ) ) {
		return false;
	}

	try {
		$result = $registry->register(
			$connector_id,
			array(
				'name'           => 'WPBP Probe',
				'type'           => 'wpbp_probe',
				'authentication' => array(
					'method' => 'none',
				),
			)
		);
	} catch ( \Throwable $e ) {
		return false;
	}

	if ( is_wp_error( $result ) ) {
		return false;
	}

	return ! empty( $result );
}
