function wpbp_connectors_api_013( string $connector_id, array $args ): string {
	if ( ! class_exists( 'WP_Connector_Registry' ) ) {
		return 'invalid';
	}

	$registry = WP_Connector_Registry::get_instance();
	if ( ! $registry ) {
		return 'invalid';
	}

	// Already-registered IDs must never be registered again.
	if ( '' !== $connector_id && $registry->is_registered( $connector_id ) ) {
		return 'exists';
	}

	if ( '' === $connector_id ) {
		return 'invalid';
	}

	// Validate the authentication array.
	if ( ! isset( $args['authentication'] ) || ! is_array( $args['authentication'] ) ) {
		return 'invalid';
	}

	$auth = $args['authentication'];
	if (
		! isset( $auth['method'] ) ||
		! is_string( $auth['method'] ) ||
		! in_array( $auth['method'], array( 'api_key', 'none' ), true )
	) {
		return 'invalid';
	}

	$result = $registry->register( $connector_id, $args );

	if ( empty( $result ) || is_wp_error( $result ) ) {
		return 'invalid';
	}

	return 'registered';
}
