function wpbp_gb_block_api_003( string $content ): array {
	$counts = array();

	if ( '' === $content || ! class_exists( 'WP_Block_Processor' ) ) {
		return $counts;
	}

	$processor = new WP_Block_Processor( $content );

	// next_block() visits every explicit block opener (including void blocks),
	// so nested blocks are counted as they are encountered.
	while ( $processor->next_block() ) {
		$block_type = $processor->get_block_type();

		if ( null === $block_type || '' === $block_type ) {
			continue;
		}

		if ( ! isset( $counts[ $block_type ] ) ) {
			$counts[ $block_type ] = 0;
		}

		$counts[ $block_type ]++;
	}

	return $counts;
}
