<?php
function wpbp_gb_block_bindings_003(): bool {
    if ( ! function_exists( 'register_block_bindings_source' ) ) {
        return false;
    }

    if ( function_exists( 'get_block_bindings_source' ) && get_block_bindings_source( 'wpbp/meta-title' ) ) {
        return true;
    }

    $result = register_block_bindings_source(
        'wpbp/meta-title',
        array(
            'label'              => __( 'WPBP Meta Title', 'wpbp' ),
            'uses_context'       => array( 'postId' ),
            'get_value_callback' => function ( array $source_args, $block_instance ) {
                $post_id = 0;

                if ( is_object( $block_instance ) && isset( $block_instance->context['postId'] ) ) {
                    $post_id = absint( $block_instance->context['postId'] );
                }

                if ( ! $post_id ) {
                    return null;
                }

                $post = get_post( $post_id );
                if ( ! $post ) {
                    return null;
                }

                if ( 'publish' !== $post->post_status && ! current_user_can( 'read_post', $post_id ) ) {
                    return null;
                }

                $value = get_post_meta( $post_id, '_wpbp_title', true );

                if ( '' === $value || ! is_scalar( $value ) ) {
                    return null;
                }

                return (string) $value;
            },
        )
    );

    return false !== $result && null !== $result;
}
