function wpbp_gb_block_editor_002( string $content ): string {
	if ( '' === $content ) {
		return '';
	}

	/**
	 * Short-circuit rendering of any block (including nested/inner blocks)
	 * whose block visibility metadata is set to hidden.
	 *
	 * This runs inside WP_Block::render() via the "pre_render_block" filter,
	 * so it is part of the server-side block rendering pipeline. On WordPress
	 * versions that already handle block visibility natively, this is simply
	 * consistent with core behavior.
	 */
	$visibility_filter = static function ( $pre_render, array $parsed_block ) {
		if (
			isset( $parsed_block['attrs']['metadata'] ) &&
			is_array( $parsed_block['attrs']['metadata'] ) &&
			array_key_exists( 'blockVisibility', $parsed_block['attrs']['metadata'] ) &&
			false === $parsed_block['attrs']['metadata']['blockVisibility']
		) {
			return '';
		}

		return $pre_render;
	};

	add_filter( 'pre_render_block', $visibility_filter, 10, 2 );

	try {
		$html = do_blocks( $content );
	} finally {
		remove_filter( 'pre_render_block', $visibility_filter, 10 );
	}

	return $html;
}
