    $block_name = 'wpbp/text-indent';

    // Avoid a duplicate registration notice if the block is already registered.
    if ( class_exists( 'WP_Block_Type_Registry' ) && WP_Block_Type_Registry::get_instance()->is_registered( $block_name ) ) {
        return true;
    }

    $result = register_block_type(
        $block_name,
        array(
            'api_version'     => 3,
            'title'           => 'Text Indent',
            'category'        => 'text',
            'attributes'      => array(
                'content' => array(
                    'type'    => 'string',
                    'default' => '',
                ),
            ),
            'supports'        => array(
                'typography' => array(
                    'textIndent' => true,
                ),
            ),
            'render_callback' => function ( array $attributes = array(), string $content = '' ): string {
                $wrapper_attributes = function_exists( 'get_block_wrapper_attributes' )
                    ? get_block_wrapper_attributes()
                    : '';

                $text = isset( $attributes['content'] ) ? (string) $attributes['content'] : '';

                return sprintf(
                    '<p %1$s>%2$s</p>',
                    $wrapper_attributes,
                    wp_kses_post( $text )
                );
            },
        )
    );

    return $result instanceof WP_Block_Type;
}
