function wpbp_gb_block_hooks_004(): bool {
	$block_name = 'wpbp/single-hook';

	$registry = WP_Block_Type_Registry::get_instance();

	// Avoid a duplicate registration notice; report the existing registration.
	if ( $registry->is_registered( $block_name ) ) {
