				array( 'label' => 'Item A', 'price' => 10 ),
				array( 'label' => 'Item B', 'price' => 20 ),
				array( 'label' => 'Item C', 'price' => 30 ),
			),
			'summary' => function () use ( $namespace ) {
				$state = wp_interactivity_state( $namespace );
				$items = isset( $state['items'] ) && is_array( $state['items'] ) ? $state['items'] : array();

				$count = count( $items );
				$total = 0;

				foreach ( $items as $item ) {
					if ( is_array( $item ) && isset( $item['price'] ) && is_numeric( $item['price'] ) ) {
						$total += $item['price'];
					}
				}

				return sprintf( '%d items, total %s', $count, $total );
			},
		)
	);

	return wp_interactivity_process_directives( $html );
}
