<?php
/**
 * Render a core/navigation-link block for a given URL and label.
 *
 * @param string $url   The link URL.
 * @param string $label The link label.
 * @return string Rendered block markup.
 */
function wpbp_gb_templates_navigation_002( string $url, string $label ): string {
	$block = array(
		'blockName'    => 'core/navigation-link',
		'attrs'        => array(
			'label' => wp_kses_post( $label ),
			'url'   => esc_url_raw( $url ),
		),
		'innerBlocks'  => array(),
		'innerHTML'    => '',
		'innerContent' => array(),
	);

	return render_block( $block );
}
