function wpbp_hooks_003( callable $callback ): bool {
	$hook     = 'wpbp_remove_filter';
	$priority = 0;

	// has_filter() returns the priority (int) when found, or false when not found.
	// Priority 0 is falsy, so strict comparisons are required.
	$before = has_filter( $hook, $callback );

	if ( false === $before || $priority !== (int) $before ) {
		return false;
	}

	$removed = remove_filter( $hook, $callback, $priority );

	if ( ! $removed ) {
		return false;
	}

	$after = has_filter( $hook, $callback );

	// Absent afterward: either not registered at all, or not at priority 0.
	return ( false === $after || $priority !== (int) $after );
}
