	// Sanitize to a valid locale format (letters, numbers, underscores, hyphens).
	if ( ! preg_match( '/^[A-Za-z0-9_\-]+$/', $locale ) ) {
		return false;
	}

	$switched = switch_to_locale( $locale );

	if ( $switched ) {
		// Work performed in the switched locale would go here.

		restore_previous_locale();
	}

	return (bool) $switched;
}
