function wpbp_mail_url_001( string $url ): string {
	$url = trim( $url );

	if ( '' === $url ) {
		return '';
	}

	$allowed_protocols = array( 'https', 'http' );

	// Use WordPress URL sanitization for storage/redirect contexts.
	$clean = esc_url_raw( $url, $allowed_protocols );

	if ( '' === $clean ) {
		return '';
	}

	// If the original input explicitly specified http(s), respect it.
	if ( preg_match( '#^https?://#i', $url ) ) {
		return $clean;
	}

	// If WordPress added a missing scheme (defaults to http://), prefer https://.
	if ( 0 === stripos( $clean, 'http://' ) ) {
		$clean = 'https://' . substr( $clean, 7 );
	}

	return $clean;
}
