<?php
/**
 * Returns HTML after WordPress applies its media tag optimizations
 * (lazy loading, decoding, srcset/sizes, width/height, fetchpriority, iframe lazy loading, etc.).
 *
 * @param string      $html    The HTML content to filter.
 * @param string|null $context Optional context (e.g. 'the_content'). Defaults to 'the_content'.
 * @return string Filtered HTML.
 */
function wpbp_media_002( string $html, ?string $context = null ): string {
	if ( '' === trim( $html ) ) {
		return $html;
	}

	if ( null === $context || '' === $context ) {
		$context = 'the_content';
	}

	if ( function_exists( 'wp_filter_content_tags' ) ) {
		$filtered = wp_filter_content_tags( $html, $context );
		return is_string( $filtered ) ? $filtered : $html;
	}

	return $html;
}
```

