<?php
/**
 * Returns WordPress image resize dimensions.
 *
 * Wraps image_resize_dimensions() which returns an array:
 * [ dst_x, dst_y, src_x, src_y, dst_w, dst_h, src_w, src_h ]
 * or false if the dimensions are invalid.
 *
 * @param int        $orig_w Original width.
 * @param int        $orig_h Original height.
 * @param int        $dest_w Requested width.
 * @param int        $dest_h Requested height.
 * @param bool|array $crop   Crop setting. Boolean or array like [ 'left', 'top' ].
 *
 * @return array|false
 */
function wpbp_media_003( int $orig_w, int $orig_h, int $dest_w, int $dest_h, bool|array $crop = false ): array|false {
	if ( ! function_exists( 'image_resize_dimensions' ) ) {
		require_once ABSPATH . 'wp-includes/media.php';
	}

	$result = image_resize_dimensions( $orig_w, $orig_h, $dest_w, $dest_h, $crop );

	return is_array( $result ) ? $result : false;
}
