```php
function wpbp_media_004( string $file ): string {
	if ( '' === $file || ! is_readable( $file ) || ! is_file( $file ) ) {
		return '';
	}

	if ( ! function_exists( 'wp_get_image_alttext' ) ) {
		if ( ! defined( 'ABSPATH' ) ) {
			return '';
		}

		$image_helper = ABSPATH . 'wp-admin/includes/image.php';

		if ( ! is_readable( $image_helper ) ) {
			return '';
		}

		require_once $image_helper;
	}

	if ( ! function_exists( 'wp_get_image_alttext' ) ) {
		return '';
	}

	$alt_text = wp_get_image_alttext( $file );

	if ( ! is_string( $alt_text ) ) {
		return '';
	}

	$alt_text = trim( $alt_text );

	return '' !== $alt_text ? $alt_text : '';
}
```

