<?php
/**
 * Returns WordPress's extension and MIME type result for an upload filename.
 *
 * Uses wp_check_filetype(), which relies only on the filename (extension)
 * and does not inspect file contents.
 *
 * @param string     $filename The filename to check.
 * @param array|null $mimes    Optional. Map of allowed mime types, where keys are
 *                             pipe-separated extensions and values are MIME types.
 *                             Defaults to WordPress's allowed mime types.
 * @return array {
 *     @type string|false $ext  File extension, or false if not allowed.
 *     @type string|false $type MIME type, or false if not allowed.
 * }
 */
function wpbp_media_005( string $filename, ?array $mimes = null ): array {
	$result = wp_check_filetype( $filename, $mimes );

	if ( ! is_array( $result ) ) {
		return array(
			'ext'  => false,
			'type' => false,
		);
	}

	return array(
		'ext'  => isset( $result['ext'] ) ? $result['ext'] : false,
		'type' => isset( $result['type'] ) ? $result['type'] : false,
	);
}
