function wpbp_post_meta_003( int $post_id, string $meta_key, string $value ): bool {
	global $wpdb;

	if ( $post_id <= 0 || '' === $meta_key ) {
		return false;
	}

	// Note: delete_post_meta() treats an empty-string value as "match any value",
	// which would delete non-matching entries. To be safe for all values, locate
	// exact matches ourselves and delete them individually by meta ID.
	$rows = $wpdb->get_results(
		$wpdb->prepare(
			"SELECT meta_id, meta_value FROM {$wpdb->postmeta} WHERE post_id = %d AND meta_key = %s",
			$post_id,
			$meta_key
		)
	);

	if ( empty( $rows ) ) {
		return false;
	}

	$deleted = false;

	foreach ( $rows as $row ) {
		if ( (string) $row->meta_value === $value ) {
			if ( delete_metadata_by_mid( 'post', (int) $row->meta_id ) ) {
				$deleted = true;
			}
		}
	}

	if ( $deleted ) {
		wp_cache_delete( $post_id, 'post_meta' );
	}

	return $deleted;
}
