<?php
/**
 * Retrieve every stored value for a multi-value post meta key.
 *
 * @param int    $post_id  The post ID.
 * @param string $meta_key The meta key to retrieve.
 * @return array Array of all stored values (empty array if none or on invalid input).
 */
function wpbp_post_meta_004( int $post_id, string $meta_key ): array {
	if ( $post_id <= 0 || '' === $meta_key ) {
		return array();
	}

	$values = get_post_meta( $post_id, $meta_key, false );

	if ( ! is_array( $values ) ) {
		return array();
	}

	return array_values( $values );
}
