function wpbp_post_meta_005( int $post_id, string $meta_key, string $json ): string {
	if ( $post_id <= 0 || '' === $meta_key ) {
		return '';
	}

	if ( ! get_post( $post_id ) ) {
		return '';
	}

	// Ensure the input is valid JSON before storing.
	json_decode( $json );
	if ( JSON_ERROR_NONE !== json_last_error() ) {
		return '';
	}

	/*
	 * WordPress metadata APIs run wp_unslash() on the value (they expect
	 * "slashed" data). Without wp_slash(), backslashes such as those in \"
	 * would be stripped, corrupting the JSON. Slash it first so the stored
	 * value is exactly the original string.
	 */
	$result = update_post_meta( $post_id, $meta_key, wp_slash( $json ) );

	$stored = get_post_meta( $post_id, $meta_key, true );

	if ( false === $result && $stored !== $json ) {
		return '';
	}

	return is_string( $stored ) ? $stored : '';
}
