	$post_type = 'wpbp_pt_005';
	$taxonomy  = 'wpbp_tax_005';

	$name = sanitize_text_field( $name );
	if ( '' === $name ) {
		return array();
	}

	$registered_post_type = false;
	$registered_taxonomy  = false;

	if ( ! post_type_exists( $post_type ) ) {
		register_post_type(
			$post_type,
			array(
				'label'  => 'WPBP Type 005',
				'public' => false,
			)
		);
		$registered_post_type = true;
	}

	if ( ! taxonomy_exists( $taxonomy ) ) {
		register_taxonomy(
			$taxonomy,
			array( $post_type ),
			array(
				'label'        => 'WPBP Taxonomy 005',
				'public'       => false,
				'hierarchical' => false,
				'rewrite'      => false,
			)
		);
		$registered_taxonomy = true;
	}

	$result  = array();
	$term_id = 0;

	$inserted = wp_insert_term( $name, $taxonomy );

	if ( is_wp_error( $inserted ) ) {
		$existing_id = $inserted->get_error_data( 'term_exists' );
		if ( $existing_id ) {
			$term_id = (int) $existing_id;
		}
	} else {
		$term_id = (int) $inserted['term_id'];
	}

	if ( $term_id > 0 ) {
		$term = get_term( $term_id, $taxonomy );
		if ( $term && ! is_wp_error( $term ) ) {
			$result = array(
				'slug'     => $term->slug,
				'taxonomy' => $term->taxonomy,
			);
		}
	}

	// Clean up the types registered by this function.
	if ( $registered_taxonomy && function_exists( 'unregister_taxonomy' ) ) {
		unregister_taxonomy( $taxonomy );
	}

	if ( $registered_post_type && function_exists( 'unregister_post_type' ) ) {
		unregister_post_type( $post_type );
	}

	return $result;
}

