 * then cleans up the registered type when possible.
 *
 * @return string The post type archive link, or an empty string on failure.
 */
function wpbp_post_types_taxonomy_007(): string {
	$post_type          = 'wpbp_item_007';
	$already_registered = post_type_exists( $post_type );
	$registered_here    = false;

	if ( ! $already_registered ) {
		$args = array(
			'label'        => 'WPBP Items 007',
			'public'       => true,
			'has_archive'  => true,
			'rewrite'      => array(
				'slug' => 'wpbp-items-007',
			),
			'show_in_rest' => true,
			'supports'     => array( 'title', 'editor' ),
		);

		$result = register_post_type( $post_type, $args );

		if ( is_wp_error( $result ) ) {
			return '';
		}

		$registered_here = true;
	}

	$link = '';

	$post_type_object = get_post_type_object( $post_type );
	if (
		$post_type_object instanceof WP_Post_Type
		&& ! empty( $post_type_object->public )
		&& ! empty( $post_type_object->has_archive )
	) {
		$archive_link = get_post_type_archive_link( $post_type );
		if ( is_string( $archive_link ) ) {
			$link = $archive_link;
		}
	}

	// Clean up only if this function registered the post type.
	if ( $registered_here && function_exists( 'unregister_post_type' ) ) {
		unregister_post_type( $post_type );
	}

	return $link;
}
