<?php
/**
 * Registers a taxonomy with a custom REST base and returns its slug.
 *
 * @return string The taxonomy slug on success, empty string on failure.
 */
function wpbp_post_types_taxonomy_008(): string {
	$taxonomy  = 'wpbp_genre_008';
	$post_type = 'wpbp_book_008';

	// Register a supporting post type if it doesn't already exist.
	$registered_post_type = false;
	if ( ! post_type_exists( $post_type ) ) {
		$pt_result = register_post_type(
			$post_type,
			array(
				'label'        => 'WPBP Books 008',
				'public'       => true,
				'show_in_rest' => true,
				'rest_base'    => 'wpbp-books-008',
				'supports'     => array( 'title', 'editor' ),
			)
		);

		if ( is_wp_error( $pt_result ) ) {
			return '';
		}
		$registered_post_type = true;
	}

	// Register the taxonomy with a custom REST base if it doesn't already exist.
	$registered_taxonomy = false;
	if ( ! taxonomy_exists( $taxonomy ) ) {
		$labels = array(
			'name'          => 'Genres 008',
			'singular_name' => 'Genre 008',
			'search_items'  => 'Search Genres',
			'all_items'     => 'All Genres',
			'edit_item'     => 'Edit Genre',
			'update_item'   => 'Update Genre',
			'add_new_item'  => 'Add New Genre',
			'new_item_name' => 'New Genre Name',
			'menu_name'     => 'Genres',
		);

		$tax_result = register_taxonomy(
			$taxonomy,
			array( $post_type ),
			array(
				'labels'                => $labels,
				'public'                => true,
				'hierarchical'          => true,
				'show_in_rest'          => true,
				'rest_base'             => 'wpbp-genres-008',
				'rest_controller_class' => 'WP_REST_Terms_Controller',
				'show_admin_column'     => true,
				'rewrite'               => array( 'slug' => 'wpbp-genre-008' ),
			)
		);

		if ( is_wp_error( $tax_result ) ) {
			if ( $registered_post_type ) {
				unregister_post_type( $post_type );
			}
			return '';
		}
		$registered_taxonomy = true;
	}

	$success = taxonomy_exists( $taxonomy );
	$rest_base = '';

	if ( $success ) {
		$tax_object = get_taxonomy( $taxonomy );
		if ( $tax_object && ! empty( $tax_object->rest_base ) ) {
			$rest_base = $tax_object->rest_base;
		}
	}

	// Clean up types registered by this function (they exist only for this call).
	if ( $registered_taxonomy && function_exists( 'unregister_taxonomy' ) ) {
		unregister_taxonomy( $taxonomy );
	}
	if ( $registered_post_type && function_exists( 'unregister_post_type' ) ) {
		unregister_post_type( $post_type );
	}

	return ( $success && 'wpbp-genres-008' === $rest_base ) ? $taxonomy : '';
}
