/**
 * Retrieve approved comments for a given post using WP_Comment_Query.
 *
 * Results are ordered deterministically: oldest first by comment date,
 * with comment ID as a tiebreaker.
 *
 * @param int $post_id The post ID.
 * @return array List of WP_Comment objects.
 */
function wpbp_queries_007( int $post_id ): array {
	$post_id = absint( $post_id );

	if ( 0 === $post_id ) {
		return array();
	}

	$query = new WP_Comment_Query();

	$comments = $query->query(
		array(
			'post_id'                   => $post_id,
			'status'                    => 'approve',
			'type'                      => 'comment',
			'orderby'                   => array( 'comment_date_gmt', 'comment_ID' ),
			'order'                     => 'ASC',
			'number'                    => 0,
			'offset'                    => 0,
			'fields'                    => '',
			'hierarchical'              => false,
			'count'                     => false,
			'no_found_rows'             => true,
			'update_comment_meta_cache' => false,
			'update_comment_post_cache' => false,
		)
	);

	return is_array( $comments ) ? array_values( $comments ) : array();
}
