        'post_type'        => 'post',
        'post_status'      => 'publish',
        'posts_per_page'   => 1,
        'suppress_filters' => false, // Allow WordPress query filters to modify the query.
    );

    $posts = get_posts( $args );

    return is_array( $posts ) ? $posts : array();
}
