<?php
/**
 * Plugin Name: WPBP Books REST Endpoint
 * Description: Registers /wp-json/wpbp/v1/books/<id> which accepts only numeric IDs.
 * Version: 1.0.0
 */

if ( ! defined( 'ABSPATH' ) ) {
    exit;
}

/**
 * Validate that the "id" argument is a numeric (digits only) value.
 *
 * @param mixed           $value   Value of the parameter.
 * @param WP_REST_Request $request Current request.
 * @param string          $param   Parameter name.
 * @return true|WP_Error
 */
function wpbp_validate_book_id( $value, $request, $param ) {
    if ( is_int( $value ) ) {
        $is_valid = $value >= 0;
    } elseif ( is_string( $value ) ) {
        $is_valid = (bool) preg_match( '/^\d+$/', $value );
    } else {
        $is_valid = false;
    }

    if ( ! $is_valid ) {
        return new WP_Error(
            'rest_invalid_param',
            sprintf(
                /* translators: %s: parameter name */
                __( '%s must be a numeric ID.', 'wpbp' ),
                $param
            ),
            array( 'status' => 400 )
        );
    }

    return true;
}

/**
 * Sanitize the validated ID into an integer.
 *
 * @param mixed $value Value of the parameter.
 * @return int
 */
function wpbp_sanitize_book_id( $value ) {
    return absint( $value );
}

/**
 * Endpoint callback: returns the ID as an integer.
 *
 * @param WP_REST_Request $request Current request.
 * @return WP_REST_Response
 */
function wpbp_get_book( WP_REST_Request $request ) {
    $id = (int) $request->get_param( 'id' );

    return rest_ensure_response( $id );
}

