<?php
/**
 * Registers item URLs as items/<item-slug> using the %wpbp_item% placeholder.
 *
 * Rewrite rules are intentionally NOT flushed here. Flush them once on plugin
 * activation/deactivation, or manually via Settings > Permalinks.
 */
function wpbp_rewrite_permalinks_001(): void {
    // Register the rewrite tag (also maps the tag to the wpbp_item query var).
    add_rewrite_tag( '%wpbp_item%', '([^/]+)', 'wpbp_item=' );

    // Register the extra permalink structure: items/<item-slug>.
    add_permastruct(
        'wpbp_item',
        'items/%wpbp_item%',
        array(
            'with_front'  => false,
            'ep_mask'     => EP_NONE,
            'paged'       => false,
            'feed'        => false,
            'forcomments' => false,
            'walk_dirs'   => false,
            'endpoints'   => false,
        )
    );

    // Ensure the wpbp_item query variable is public (guard against duplicate registration).
    if ( ! has_filter( 'query_vars', 'wpbp_rewrite_permalinks_001_query_vars' ) ) {
        add_filter( 'query_vars', 'wpbp_rewrite_permalinks_001_query_vars' );
    }
}

/**
 * Adds the wpbp_item query variable to the list of public query vars.
 *
 * @param array $vars Existing public query vars.
 * @return array
 */
function wpbp_rewrite_permalinks_001_query_vars( array $vars ): array {
    if ( ! in_array( 'wpbp_item', $vars, true ) ) {
        $vars[] = 'wpbp_item';
    }
    return $vars;
}

add_action( 'init', 'wpbp_rewrite_permalinks_001' );
