<?php
/**
 * Register a top-priority rewrite rule for URLs like wpbp-rule/<code>,
 * mapping the captured code to the wpbp_rule query variable.
 *
 * Note: Rewrite rules are intentionally NOT flushed here. Flush them once on
 * plugin/theme activation (register_activation_hook) or manually via
 * Settings > Permalinks.
 */
function wpbp_rewrite_permalinks_002(): void {
    // Make sure the query variable is recognized by WordPress.
    add_filter(
        'query_vars',
        static function ( array $vars ): array {
            if ( ! in_array( 'wpbp_rule', $vars, true ) ) {
                $vars[] = 'wpbp_rule';
            }
            return $vars;
        }
    );

    // Register the rewrite rule at the top of the rules list.
    add_rewrite_rule(
        '^wpbp-rule/([^/]+)/?$',
        'index.php?wpbp_rule=$matches[1]',
        'top'
    );
}

// Hook into init so rewrite APIs are available and the rule is registered on every request.
add_action( 'init', 'wpbp_rewrite_permalinks_002' );
