function wpbp_roles_caps_002(): bool {
    $cap  = 'wpbp_temp_cap';
    $role = get_role( 'subscriber' );

    if ( ! ( $role instanceof WP_Role ) ) {
        return false;
    }

    // Ensure a clean starting state so the add transition is meaningful.
    if ( $role->has_cap( $cap ) ) {
        $role->remove_cap( $cap );
        $role = get_role( 'subscriber' );
        if ( ! ( $role instanceof WP_Role ) ) {
            return false;
        }
    }

    // Add the capability and verify.
    $role->add_cap( $cap );
    $role = get_role( 'subscriber' );
    $added = ( $role instanceof WP_Role )
        && $role->has_cap( $cap )
        && isset( $role->capabilities[ $cap ] )
        && $role->capabilities[ $cap ];

    // Always attempt removal to leave the role clean.
    if ( $role instanceof WP_Role ) {
        $role->remove_cap( $cap );
    } else {
        $role = get_role( 'subscriber' );
        if ( $role instanceof WP_Role ) {
            $role->remove_cap( $cap );
        }
    }

    // Verify removal.
    $role = get_role( 'subscriber' );
    $removed = ( $role instanceof WP_Role )
        && ! $role->has_cap( $cap )
        && ! array_key_exists( $cap, $role->capabilities );

    return (bool) ( $added && $removed );
}
