function wpbp_roles_caps_003( int $user_id, string $cap ): bool {
    $cap = trim( $cap );

    if ( $user_id <= 0 || '' === $cap ) {
        return false;
    }

    $user = get_userdata( $user_id );
    if ( ! $user ) {
        return false;
    }

    $previous_user_id = get_current_user_id();

    wp_set_current_user( $user_id );

    try {
        $can = current_user_can( $cap );
    } finally {
        // Restore the original user to avoid side effects.
        wp_set_current_user( $previous_user_id );
    }

    return (bool) $can;
}
