function wpbp_roles_caps_005( int $user_id, string $cap ): bool {
    $cap = trim( $cap );

    if ( $user_id <= 0 || '' === $cap ) {
        return false;
    }

    $user = get_userdata( $user_id );

    if ( ! ( $user instanceof WP_User ) || ! $user->exists() ) {
        return false;
    }

    // Grant the capability directly to the user.
    $user->add_cap( $cap, true );

    // Reload the user to ensure fresh capability data.
    if ( function_exists( 'clean_user_cache' ) ) {
        clean_user_cache( $user_id );
    }

    $fresh_user = new WP_User( $user_id );

    if ( ! $fresh_user->exists() ) {
        return false;
    }

    // Verify using WP_User capability check and WordPress capability check.
    return $fresh_user->has_cap( $cap ) && user_can( $fresh_user, $cap );
}
