<?php
/**
 * Check whether a specific user has the requested capability,
 * without switching the current user.
 *
 * @param int    $user_id User ID.
 * @param string $cap     Capability (or role) to check.
 * @return bool
 */
function wpbp_roles_caps_007( int $user_id, string $cap ): bool {
	$user_id = absint( $user_id );
	$cap     = trim( $cap );

	if ( 0 === $user_id || '' === $cap ) {
		return false;
	}

	$user = get_userdata( $user_id );

	if ( ! ( $user instanceof WP_User ) || ! $user->exists() ) {
		return false;
	}

	// Uses WP_User::has_cap(), which applies map_meta_cap and the user_has_cap filter.
	return (bool) $user->has_cap( $cap );
}
