<?php
/**
 * Returns the primitive capabilities WordPress requires for the given user
 * to delete the given post, using WordPress' meta capability mapping.
 *
 * @param int $user_id The user ID.
 * @param int $post_id The post ID.
 * @return array List of primitive capabilities (e.g. 'delete_posts', 'delete_others_posts', ...).
 */
function wpbp_roles_caps_008( int $user_id, int $post_id ): array {
	if ( ! function_exists( 'map_meta_cap' ) ) {
		return array( 'do_not_allow' );
	}

	$caps = map_meta_cap( 'delete_post', $user_id, $post_id );

	if ( ! is_array( $caps ) ) {
		return array( 'do_not_allow' );
	}

	return array_values( $caps );
}
