function wpbp_security_005( string $url ): string {
	$url = trim( $url );

	if ( '' === $url ) {
		return '';
	}

	$first_char = $url[0];

	// Mirror the conditions under which esc_url() would prepend "http://",
	// but prepend "https://" instead so HTTPS is preferred.
	$is_relative_or_fragment = in_array( $first_char, array( '/', '#', '?' ), true );
	$is_php_file             = (bool) preg_match( '/^[a-z0-9-]+?\.php/i', $url );
	$has_colon               = ( false !== strpos( $url, ':' ) );
	$looks_like_host_port    = (bool) preg_match( '#^[^/?\#:]+:\d+(?:[/?\#]|$)#', $url );

	if ( ! $is_relative_or_fragment && ! $is_php_file && ( ! $has_colon || $looks_like_host_port ) ) {
		$url = 'https://' . $url;
	}

	return esc_url( $url, array( 'https', 'http' ) );
}
