<?php
/**
 * Update the 'wpbp_nested' option with a sanitized key/value pair,
 * preserving any existing entries.
 *
 * @param string $key   The option entry key.
 * @param string $value The plain-text value to store.
 * @return array The full updated option array.
 */
function wpbp_settings_options_003( string $key, string $value ): array {
	$option_name = 'wpbp_nested';

	$options = get_option( $option_name, array() );
	if ( ! is_array( $options ) ) {
		$options = array();
	}

	$clean_key   = sanitize_key( $key );
	$clean_value = sanitize_text_field( $value );

	// Do not store entries under an empty key.
	if ( '' === $clean_key ) {
		return $options;
	}

	$options[ $clean_key ] = $clean_value;

	update_option( $option_name, $options );

	return $options;
}
