function wpbp_shortcodes_004( string $content, string $tag ): bool {
	if ( '' === $content || '' === $tag || false === strpos( $content, '[' ) ) {
		return false;
	}

	// Only registered shortcodes can be detected.
	if ( ! shortcode_exists( $tag ) ) {
		return false;
	}

	// Regex built from all registered tags so nested registered shortcodes are parsed too.
	$pattern = get_shortcode_regex();

	if ( ! preg_match_all( '/' . $pattern . '/', $content, $matches, PREG_SET_ORDER ) || empty( $matches ) ) {
		return false;
	}

	foreach ( $matches as $shortcode ) {
		// Skip escaped shortcodes like [[tag]].
		$is_escaped = ( '[' === $shortcode[1] && ']' === $shortcode[6] );

		if ( ! $is_escaped && $tag === $shortcode[2] ) {
			return true;
		}

		// Check nested content of enclosing shortcodes.
		if ( ! empty( $shortcode[5] ) && wpbp_shortcodes_004( $shortcode[5], $tag ) ) {
			return true;
		}
	}

	return false;
}
